package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.CaptureRequestBodyVO;

class CaptureRequestBodyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of capture request body of observability config")
  void test_capture_request_body_value_holder_assign_plain_value() {
    Object holder = new Object();
    CaptureRequestBodyValueHolder<Object> value = new CaptureRequestBodyValueHolder<>(holder);
    Assertions.assertSame(holder, value.captureRequestBody(true), "Setters must return the holder");
    Assertions.assertTrue(value.getCaptureRequestBodyValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getCaptureRequestBody().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of capture request body of observability config")
  void test_capture_request_body_value_holder_assign_value_object() {
    Object holder = new Object();
    CaptureRequestBodyValueHolder<Object> value = new CaptureRequestBodyValueHolder<>(holder);
    CaptureRequestBodyVO vo = CaptureRequestBodyVO.from(true);
    Assertions.assertFalse(value.getCaptureRequestBodyValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.captureRequestBody(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCaptureRequestBodyValue().orElseThrow());
    Assertions.assertSame(holder, value.captureRequestBody(Optional.empty()));
    Assertions.assertFalse(value.getCaptureRequestBodyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.captureRequestBody(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCaptureRequestBodyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of capture request body of observability config against the original")
  void test_capture_request_body_value_holder_read() {
    Object holder = new Object();
    CaptureRequestBodyValueHolder<Object> value = new CaptureRequestBodyValueHolder<>(holder);
    CaptureRequestBodyVO vo = CaptureRequestBodyVO.from(true);
    CaptureRequestBodyVO other = CaptureRequestBodyVO.from(true);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getCaptureRequestBodyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCaptureRequestBody(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readCaptureRequestBody(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.captureRequestBody(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCaptureRequestBody(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCaptureRequestBody(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of capture request body of observability config")
  void test_capture_request_body_value_holder_unset() {
    Object holder = new Object();
    CaptureRequestBodyValueHolder<Object> value = new CaptureRequestBodyValueHolder<>(holder);
    CaptureRequestBodyVO vo = CaptureRequestBodyVO.from(true);
    value.captureRequestBody(vo);
    Assertions.assertSame(holder,
        value.unsetCaptureRequestBodyIfMatches("captureRequestBody_other"));
    Assertions.assertTrue(value.getCaptureRequestBodyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCaptureRequestBodyIfMatches("captureRequestBody"));
    Assertions.assertFalse(value.getCaptureRequestBodyValue().isPresent(),
        "The field name must clear the value");
    value.captureRequestBody(vo);
    Assertions.assertSame(holder, value.unsetCaptureRequestBody());
    Assertions.assertFalse(value.getCaptureRequestBodyValue().isPresent(),
        "Unset must clear the value");
  }
}
